2395:     param(
2396:         [Parameter(Mandatory)][string]$Method,
2397:         [string]$ParamsYaml = ''
2398:     )
2399: 
2400:     # Local plugin-shim verbs: record the boolean outcome on the script-scoped
2401:     # success flag (so the script-entry exit code is truthful) and return without
2402:     # emitting the boolean to stdout. Emitting it leaked "True" lines, and leaving
2403:     # the flag unset made the script-entry exit 1 even on a successful persist.
2404:     switch -Wildcard ($Method) {
2405:         'workflow.sessionlog.beginTurn'       { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowBeginTurn -ParamsYaml $ParamsYaml); return }
2406:         'workflow.sessionlog.openSession'     { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowOpenSession -ParamsYaml $ParamsYaml); return }
